window.applyLanguage = (lang) => {
    let t = translations[lang];
    if (!t) return;
    document.documentElement.lang = lang;
    document.documentElement.dir = "ar" === lang ? "rtl" : "ltr";
    if (document.getElementById("current-lang")) {
        document.getElementById("current-lang").innerText = lang.toUpperCase();
    }
    document.querySelectorAll("[data-lang-key]").forEach(el => {
        let key = el.getAttribute("data-lang-key");
        if (t[key]) el.innerHTML = t[key];
    });
    document.querySelectorAll("[data-lang-placeholder]").forEach(el => {
        let key = el.getAttribute("data-lang-placeholder");
        if (t[key]) el.placeholder = t[key];
    });
    let mobileMenu = document.getElementById("mobile-menu");
    if (mobileMenu && !mobileMenu.classList.contains("opacity-0")) {
        mobileMenu.classList.add("opacity-0", "pointer-events-none");
        let mobileBtn = document.getElementById("mobile-menu-btn");
        if (mobileBtn) mobileBtn.innerHTML = '<i class="fas fa-bars"></i>';
    }
};

const serviceIcons = [
    '<i class="fas fa-building"></i>', '<i class="fas fa-cube"></i>',
    '<i class="fas fa-laptop-code"></i>', '<i class="fas fa-home"></i>',
    '<i class="fas fa-ruler-combined"></i>', '<i class="fas fa-tasks"></i>',
    '<i class="fas fa-handshake"></i>', '<i class="fas fa-bolt"></i>'
];

window.openModal = (id) => {
    let modal = document.getElementById("service-modal");
    let title = document.getElementById("modal-title");
    let desc = document.getElementById("modal-desc");
    let icon = document.getElementById("modal-icon");
    let btn = document.getElementById("modal-whatsapp-btn");
    
    let pathArray = window.location.pathname.split('/').filter(p => p);
    let validLangs = ['en', 'ar', 'tr', 'es'];
    let lang = (pathArray.length > 0 && validLangs.includes(pathArray[0])) ? pathArray[0] : 'en';
    
    let t = translations[lang];
    let serviceTitle = t[`srv_${id}_title`];
    if (title) title.innerText = serviceTitle;
    if (desc) desc.innerText = t[`srv_${id}_detail`];
    if (icon) icon.innerHTML = serviceIcons[id - 1];
    let msg = `${t.wa_msg} ${serviceTitle}`;
    if (btn) btn.href = `https://wa.me/905315865489?text=${encodeURIComponent(msg)}`;
    if (modal) {
        modal.classList.remove("hidden");
        document.body.style.overflow = "hidden";
    }
};

window.closeModal = () => {
    let modal = document.getElementById("service-modal");
    if (modal) {
        modal.classList.add("hidden");
        document.body.style.overflow = "auto";
    }
};

document.addEventListener("DOMContentLoaded", () => {
    // 1. Language Init & SEO Folder Routing Fix
    let validLangs = ['en', 'ar', 'tr', 'es'];
    let pathArray = window.location.pathname.split('/').filter(p => p);
    let currentLang = 'en'; // Default to English if no lang folder found

    if (pathArray.length > 0 && validLangs.includes(pathArray[0])) {
        currentLang = pathArray[0];
    }
    
    window.applyLanguage(currentLang);

    // Language Switcher Logic
    let langBtns = document.querySelectorAll(".arch-lang-btn, .lang-btn-classic");
    langBtns.forEach(btn => {
        btn.addEventListener("click", e => {
            e.preventDefault();
            let targetLang = e.currentTarget.getAttribute("data-lang-target");
            if (targetLang) {
                let currentUrl = window.location.pathname;
                let cleanPath = currentUrl.replace(/^\/(ar|tr|es)(\/|$)/, '/');
                if (!cleanPath.startsWith('/')) cleanPath = '/' + cleanPath;
                let newPath = targetLang === 'en' ? cleanPath : `/${targetLang}${cleanPath}`;
                newPath = newPath.replace(/\/\//g, '/');
                window.location.href = newPath;
            }
        });
    });

    window.mafiaMusic = document.getElementById("mafia-audio");
    if (window.mafiaMusic) window.mafiaMusic.volume = 0.25;
    let volSlider = document.getElementById("mafia-vol-slider");
    if (volSlider) {
        volSlider.addEventListener("input", e => {
            if (window.mafiaMusic) window.mafiaMusic.volume = e.target.value;
        });
    }

    let isMobileDevice = window.innerWidth <= 768;
    let introCanvas = document.getElementById("webgl-canvas");
    let masterIntro = document.getElementById("cinematic-master-container");
    let triggerBtn = document.getElementById("trigger-btn");
    let introSceneActive = true;
    let introRenderReq;
    let scene, camera, renderer, group, pointLight, sphere1, sphere2, spotLight, pLight2, ambientLight, particles;
    let objects = [];

    if (introCanvas) {
        introCanvas.style.display = "none";
    }

    setTimeout(() => {
        introSceneActive = false;
        if (typeof gsap === "undefined") {
            document.querySelector(".brand-subtitle").style.opacity = 1;
            document.querySelector(".brand-title").style.opacity = 1;
            document.querySelector(".brand-tagline").style.opacity = 1;
            document.querySelector(".magnetic-btn").style.opacity = 1;
            return;
        }

        let tl = gsap.timeline();
        tl.to(".brand-subtitle", { opacity: 1, y: 0, duration: 1, ease: "power3.out" }, 0.2);
        tl.to(".brand-title", { opacity: 1, scale: 1, y: 0, duration: 1.5, ease: "expo.out" }, 0.4);
        tl.to(".brand-tagline", { opacity: 1, y: 0, duration: 1, ease: "power3.out" }, 0.7);
        tl.to(".magnetic-btn", { opacity: 1, duration: 1, ease: "power2.out", onComplete() {
            let btn = document.getElementById("trigger-btn");
            if (btn) btn.classList.add("active-pulse");
        } }, 1);

    }, 300);

    if (triggerBtn && masterIntro) {
        triggerBtn.addEventListener("click", () => {
            triggerBtn.classList.remove("active-pulse");
            if (window.mafiaMusic) {
                let p = window.mafiaMusic.play();
                if (p !== undefined) p.catch(e => console.log("Audio play blocked by browser:", e));
            }

            if (introCanvas && typeof THREE !== "undefined" && !isMobileDevice) {
                introCanvas.style.display = "block";
                scene = new THREE.Scene();
                scene.fog = new THREE.FogExp2(65793, 0.025);
                camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.1, 1000);
                camera.position.set(0, 4, 18);
                camera.lookAt(0, 0, 0);

                renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: "high-performance" });
                renderer.setSize(window.innerWidth, window.innerHeight);
                renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
                renderer.toneMapping = THREE.ACESFilmicToneMapping;
                renderer.toneMappingExposure = 1.3;
                introCanvas.appendChild(renderer.domElement);

                let bGeo = new THREE.BufferGeometry();
                let bPos = new Float32Array(1500);
                for (let w = 0; w < 1500; w++) bPos[w] = (Math.random() - 0.5) * 60;
                bGeo.setAttribute("position", new THREE.BufferAttribute(bPos, 3));
                let pMat = new THREE.PointsMaterial({ size: 0.15, color: 13938487, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending });
                particles = new THREE.Points(bGeo, pMat);
                scene.add(particles);
                
                renderer.render(scene, camera);
            }

            if (typeof gsap !== "undefined") {
                let tl = gsap.timeline();
                tl.to("#ui-overlay", { opacity: 0, scale: 1.1, duration: 0.4, ease: "power2.in" }, 0);
                
                if (!isMobileDevice && particles) {
                    tl.to(particles.rotation, { y: 2, duration: 1.4, ease: "power4.in" }, 0);
                    tl.to(camera.position, { z: -30, y: 2, duration: 1.4, ease: "power4.in" }, 0);
                    tl.add(() => {
                        scene.clear();
                        renderer.dispose();
                        renderer.forceContextLoss();
                    }, 1.2);
                }

                tl.to(".door-right", { x: "0%", duration: 0.6, ease: "expo.in" }, 0.6);
                tl.to(".door-left", { x: "0%", duration: 0.6, ease: "expo.in" }, 0.6);
                
                tl.add(() => {
                    masterIntro.remove();
                    document.body.classList.remove("intro-active");
                    setTimeout(() => window.dispatchEvent(new Event("resize")), 50);
                }, 1.2);
                
                tl.to(".door-right", { x: "100%", duration: 1.2, ease: "power4.inOut" }, 1.5);
                tl.to(".door-left", { x: "-100%", duration: 1.2, ease: "power4.inOut" }, 1.5);
                tl.add(() => { document.querySelectorAll(".transition-door").forEach(e => e.remove()); }, 2.8);
            } else {
                masterIntro.remove();
                document.body.classList.remove("intro-active");
                document.querySelectorAll(".transition-door").forEach(e => e.remove());
            }
        });
    }

    let classicSceneContainer = document.getElementById("scene-container");
    if (classicSceneContainer && typeof THREE !== "undefined" && !isMobileDevice) {
        let t = new THREE.Scene();
        let a = new THREE.PerspectiveCamera(45, classicSceneContainer.clientWidth / classicSceneContainer.clientHeight, 0.1, 100);
        a.position.set(8, 5, 8);
        let i = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        i.setSize(classicSceneContainer.clientWidth, classicSceneContainer.clientHeight);
        i.shadowMap.enabled = true;
        i.shadowMap.type = THREE.PCFSoftShadowMap;
        classicSceneContainer.appendChild(i.domElement);

        let o = new THREE.Group();
        t.add(o);

        let r = new THREE.MeshStandardMaterial({ color: 2763306, roughness: 0.8 });
        let n = new THREE.MeshStandardMaterial({ color: 1118481, roughness: 0.9 });
        let s = new THREE.MeshStandardMaterial({ color: 328965, roughness: 0.2, metalness: 0.5 });
        let l = new THREE.MeshStandardMaterial({ color: 13149277, emissive: 13149277, emissiveIntensity: 1 });
        let c = new THREE.MeshBasicMaterial({ color: 13149277, wireframe: true, transparent: true, opacity: 0.3 });

        let d = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), r);
        d.rotation.x = -Math.PI / 2; d.receiveShadow = true; o.add(d);

        let m = new THREE.Mesh(new THREE.BoxGeometry(3, 0.5, 1), n);
        m.position.set(0, 0.25, -2); m.castShadow = true; o.add(m);

        let u = new THREE.Mesh(new THREE.BoxGeometry(3, 1, 0.3), n);
        u.position.set(0, 0.75, -2.35); u.castShadow = true; o.add(u);

        let p = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.4, 1), s);
        p.position.set(0, 0.2, 0); p.castShadow = true; o.add(p);

        let g = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.05, 16), s);
        g.position.set(-3, 0.025, -2); o.add(g);

        let $ = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 2, 8), s);
        $.position.set(-3, 1, -2); o.add($);

        let h = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.3, 0.3, 16), l);
        h.position.set(-3, 2, -2); o.add(h);

        let y = new THREE.AmbientLight(4210752, 0.5);
        t.add(y);

        let v = new THREE.PointLight(16768426, 2, 10);
        v.position.set(-3, 1.8, -2); v.castShadow = true; o.add(v);

        let f = new THREE.DirectionalLight(4210752, 1);
        f.position.set(5, 5, -5); t.add(f);

        let b = [
            { mesh: d, mat: r }, { mesh: m, mat: n }, { mesh: u, mat: n },
            { mesh: p, mat: s }, { mesh: g, mat: s }, { mesh: $, mat: s }
        ];

        let lightToggle = document.getElementById("lightToggle");
        if (lightToggle) {
            lightToggle.addEventListener("change", e => {
                let checked = e.target.checked;
                v.intensity = checked ? 2 : 0;
                l.emissiveIntensity = checked ? 1 : 0.1;
                y.intensity = checked ? 0.5 : 0.1;
            });
        }

        let wireframeToggle = document.getElementById("wireframeToggle");
        if (wireframeToggle) {
            wireframeToggle.addEventListener("change", e => {
                let checked = e.target.checked;
                b.forEach(item => { item.mesh.material = checked ? c : item.mat; });
            });
        }

        if (typeof THREE.OrbitControls !== "undefined") {
            let controls = new THREE.OrbitControls(a, i.domElement);
            controls.enableDamping = true;
            controls.autoRotate = false;
            controls.enableZoom = false;
        }

        let animateWireframe = () => {
            requestAnimationFrame(animateWireframe);
            o.rotation.y += 0.002;
            i.render(t, a);
        };
        animateWireframe();

        window.addEventListener("resize", () => {
            a.aspect = classicSceneContainer.clientWidth / classicSceneContainer.clientHeight;
            a.updateProjectionMatrix();
            i.setSize(classicSceneContainer.clientWidth, classicSceneContainer.clientHeight);
        });
    }

    let drawCanvas = (id, func) => {
        let canvas = document.getElementById(id);
        if (!canvas) return;
        let ctx = canvas.getContext("2d");
        let resize = () => { if(canvas.parentElement) { canvas.width = canvas.parentElement.clientWidth; canvas.height = canvas.parentElement.clientHeight; } };
        window.addEventListener("resize", resize); resize();
        let step = 0;
        let animate = () => { ctx.clearRect(0, 0, canvas.width, canvas.height); func(ctx, canvas.width, canvas.height, step++); requestAnimationFrame(animate); };
        animate();
    };
    drawCanvas("canvas1", (ctx, w, h, step) => { ctx.strokeStyle = "rgba(200, 164, 93, 0.8)"; ctx.lineWidth = 1.5; let pulse = (Math.sin(0.02 * step) + 1) / 2 * w; ctx.beginPath(); ctx.moveTo(w / 4, h / 4); ctx.lineTo(w / 4 + pulse / 2, h / 4); ctx.stroke(); ctx.strokeRect(w / 4, h / 4, w / 2, h / 2); });
    drawCanvas("canvas2", (ctx, w, h, step) => { ctx.fillStyle = "rgba(200, 164, 93, 0.6)"; for (let i = 0; i < 6; i++) ctx.fillRect(w / 5, h / 4 + 30 * i, (Math.sin(0.05 * step + i) + 1.5) * 40, 6); });
    drawCanvas("canvas3", (ctx, w, h, step) => { ctx.strokeStyle = "rgba(200, 164, 93, 0.4)"; for (let i = 0; i < w; i += 40) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 40 * Math.sin(0.02 * step + i), h); ctx.stroke(); } });
    drawCanvas("canvas4", (ctx, w, h, step) => { ctx.fillStyle = "rgba(200, 164, 93, 0.7)"; ctx.beginPath(); ctx.arc(w / 2, h / 2, 50 * Math.abs(Math.sin(0.03 * step)), 0, 2 * Math.PI); ctx.fill(); ctx.strokeStyle = "rgba(200, 164, 93, 0.3)"; ctx.beginPath(); ctx.arc(w / 2, h / 2, 100 * Math.abs(Math.sin(0.015 * step)), 0, 2 * Math.PI); ctx.stroke(); });

    if (typeof gsap !== "undefined" && typeof ScrollTrigger !== "undefined") {
        gsap.registerPlugin(ScrollTrigger);
        gsap.from(".gsap-hero > *", { y: 50, opacity: 0, duration: 1, stagger: 0.2, ease: "power3.out", delay: 0.5 });
        gsap.utils.toArray(".gsap-fade-up").forEach(e => { gsap.from(e, { scrollTrigger: { trigger: e, start: "top 85%", toggleActions: "play none none none" }, y: 50, opacity: 0, duration: 0.8, ease: "power2.out" }); });
    }

    if (!window.matchMedia("(pointer: coarse)").matches) {
        let cursor = document.querySelector(".cursor-follower");
        if (cursor) {
            window.addEventListener("mousemove", e => { cursor.animate({ left: e.clientX + "px", top: e.clientY + "px" }, { duration: 400, fill: "forwards" }); });
            document.querySelectorAll("a, button, input, textarea, .glass-panel").forEach(e => {
                e.addEventListener("mouseenter", () => cursor.style.transform = "translate(-50%, -50%) scale(1.8)");
                e.addEventListener("mouseleave", () => cursor.style.transform = "translate(-50%, -50%) scale(1)");
            });
        }
    }

    let langSelector = document.querySelector(".lang-selector");
    if (langSelector) {
        langSelector.addEventListener("click", e => { e.stopPropagation(); langSelector.classList.toggle("open"); });
        document.addEventListener("click", () => langSelector.classList.remove("open"));
    }

    let navbar = document.getElementById("navbar");
    if (navbar) {
        window.addEventListener("scroll", () => {
            if (window.scrollY > 50) {
                navbar.classList.add("bg-black/90", "backdrop-blur-md", "border-white/10", "py-4");
                navbar.classList.remove("py-6", "border-transparent");
            } else {
                navbar.classList.remove("bg-black/90", "backdrop-blur-md", "py-4", "border-white/10");
                navbar.classList.add("py-6", "border-transparent");
            }
        });
    }

    let mobileBtn = document.getElementById("mobile-menu-btn");
    let mobileMenu = document.getElementById("mobile-menu");
    if (mobileBtn && mobileMenu) {
        mobileBtn.addEventListener("click", () => {
            mobileMenu.classList.toggle("opacity-0");
            mobileMenu.classList.toggle("pointer-events-none");
            mobileBtn.innerHTML = mobileMenu.classList.contains("opacity-0") ? '<i class="fas fa-bars"></i>' : '<i class="fas fa-times"></i>';
        });
        document.querySelectorAll(".mobile-link").forEach(link => {
            link.addEventListener("click", () => {
                mobileMenu.classList.add("opacity-0", "pointer-events-none");
                mobileBtn.innerHTML = '<i class="fas fa-bars"></i>';
            });
        });
    }

    document.querySelectorAll(".portfolio-trigger").forEach(btn => {
        btn.addEventListener("click", e => {
            e.preventDefault();
            let classic = document.getElementById("classic-site");
            let cinematic = document.getElementById("cinematic-portfolio");
            if (classic) classic.style.display = "none";
            if (cinematic) {
                cinematic.style.display = "block";
                cinematic.scrollTo(0, 0);
            }
            let validLangs = ['en', 'ar', 'tr', 'es'];
            let pathArray = window.location.pathname.split('/').filter(p => p);
            let lang = (pathArray.length > 0 && validLangs.includes(pathArray[0])) ? pathArray[0] : 'en';
            
            document.querySelectorAll(".arch-lang-btn").forEach(lb => {
                lb.classList.remove("active");
                if (lb.getAttribute("data-lang-target") === lang) lb.classList.add("active");
            });
        });
    });

    let backBtn = document.getElementById("back-to-classic");
    if (backBtn) {
        backBtn.addEventListener("click", () => {
            let classic = document.getElementById("classic-site");
            let cinematic = document.getElementById("cinematic-portfolio");
            let archBgAudio = document.getElementById("arch-bg-audio");
            if (cinematic) cinematic.style.display = "none";
            if (classic) classic.style.display = "block";
            if (archBgAudio) archBgAudio.pause();
            setTimeout(() => window.dispatchEvent(new Event("resize")), 50);
        });
    }

    let archSplash = document.getElementById("arch-splash");
    let archEnterBtn = document.getElementById("arch-enter-btn");
    let archWelcomeMsg = document.getElementById("arch-welcome-msg");
    let archMain = document.getElementById("arch-main");
    let archBgAudio = document.getElementById("arch-bg-audio");
    let archVolSlider = document.getElementById("arch-vol-slider");
    let archPlayBtns = document.querySelectorAll(".arch-play-btn");

    if (archVolSlider && archBgAudio) {
        archVolSlider.addEventListener("input", e => { archBgAudio.volume = e.target.value; });
    }

    if (archEnterBtn && archSplash) {
        archEnterBtn.addEventListener("click", e => {
            e.preventDefault();
            if (window.mafiaMusic) window.mafiaMusic.pause();
            if (archBgAudio) {
                archBgAudio.muted = false;
                archBgAudio.currentTime = 0;
                archBgAudio.volume = parseFloat(archVolSlider ? archVolSlider.value : 0.3) || 0.3;
                let playPromise = archBgAudio.play();
                if (playPromise !== undefined) playPromise.catch(e => { console.warn("Autoplay blocked:", e); setTimeout(() => archBgAudio.play(), 50); });
            }
            archEnterBtn.classList.add("arch-fade-out-element");
            if (archWelcomeMsg) setTimeout(() => { archWelcomeMsg.classList.add("arch-show-welcome"); }, 200);
            setTimeout(() => {
                archSplash.classList.add("arch-fade-out");
                setTimeout(() => {
                    let cp = document.getElementById("cinematic-portfolio");
                    if (cp) cp.style.overflowY = "auto";
                    if (archMain) archMain.classList.add("arch-is-ready");
                    archSplash.style.display = "none";
                }, 1000);
            }, 2000);
        });
    }

    if (document.getElementById("cinematic-portfolio")) {
        let obs = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add("arch-in-view");
                    observer.unobserve(entry.target);
                }
            });
        }, { root: document.getElementById("cinematic-portfolio"), rootMargin: "0px 0px -10% 0px", threshold: 0.1 });
        document.querySelectorAll(".arch-project-row").forEach(row => obs.observe(row));
    }

    function toggleBtnText(btn, isPlaying) {
        btn.innerHTML = "";
        let langs = {
            en: isPlaying ? "⏸ Pause Audio" : "▶ Play Audio",
            ar: isPlaying ? "⏸ إيقاف الصوت" : "▶ تشغيل الصوت",
            tr: isPlaying ? "⏸ Sesi Durdur" : "▶ Sesi Oynat",
            es: isPlaying ? "⏸ Pausar Audio" : "▶ Reproducir Audio"
        };
        for (let [lang, text] of Object.entries(langs)) {
            let span = document.createElement("span");
            span.setAttribute("data-lang-content", lang);
            span.textContent = text;
            btn.appendChild(span);
        }
    }

    archPlayBtns.forEach(btn => {
        btn.addEventListener("click", function() {
            let audio = this.nextElementSibling;
            if (audio) {
                if (audio.paused) {
                    if (archBgAudio) archBgAudio.pause();
                    document.querySelectorAll(".arch-project-audio").forEach(a => { a.pause(); a.currentTime = 0; });
                    archPlayBtns.forEach(b => toggleBtnText(b, false));
                    audio.play();
                    toggleBtnText(this, true);
                } else {
                    audio.pause();
                    toggleBtnText(this, false);
                    if (archBgAudio) archBgAudio.play();
                }
            }
        });
        let audio = btn.nextElementSibling;
        if (audio) {
            audio.addEventListener("ended", function() {
                toggleBtnText(btn, false);
                if (archBgAudio) archBgAudio.play();
            });
        }
    });
});